$rootId=(int)($a['original_article_id']?:$a['id']);$translations=query_all("SELECT a.language,a.slug FROM articles a WHERE ".published_where()." AND (a.id=? OR a.original_article_id=?)",[$rootId,$rootId]);$alternates=[];foreach($translations as $translation)if(in_array($translation['language'],['rw','en'],true))$alternates[$translation['language']]=absolute_url('article.php?slug='.rawurlencode($translation['slug']).'&lang='.rawurlencode($translation['language']));if($alternates){$defaultLanguage=(string)cfg('default_language','en');$alternates['x-default']=$alternates[$defaultLanguage]??reset($alternates);}
