render_header($a['title'],$a['summary'],$requestedLanguage,$alternates,$socialImage,'article');
$schema=['@context'=>'https://schema.org','@type'=>'NewsArticle','headline'=>$a['title'],'description'=>$a['summary'],'inLanguage'=>$a['language'],'datePublished'=>date(DATE_ATOM,strtotime($a['published_at'])),'dateModified'=>date(DATE_ATOM,strtotime($a['updated_at'])),'author'=>['@type'=>'Person','name'=>$a['author_name'],'url'=>absolute_url('author.php?id='.$a['author_id'].'&lang='.rawurlencode($requestedLanguage))],'publisher'=>['@type'=>'Organization','name'=>cfg('site_name'),'url'=>cfg('app_url')],'mainEntityOfPage'=>absolute_url('article.php?slug='.rawurlencode($a['slug']).'&lang='.rawurlencode($requestedLanguage)),'isAccessibleForFree'=>!$a['is_premium']];
if($socialImage) $schema['image']=[$socialImage];
