 ?['home'=>'HOME','key_points'=>'KEY POINTS','published'=>'Published','updated'=>'Updated','copy'=>'COPY LINK ↗','demo_title'=>'TEST EXAMPLE:','demo_body'=>'This article is demo content. It is not verified current news and must not be presented as a real report.','photo'=>'Illustrative image','story'=>'STORY','reporting'=>'HOW WE REPORT ↗','video'=>'Story video','sources'=>'Sources shared with readers','correction'=>'CORRECTION','contact'=>'Found an error in this story?','contact_link'=>'Tell the newsroom.','facts'=>'Verified reporting must be supported by checkable information.','related'=>'More stories','related_i'=>'to read.']
 :['home'=>'AHABANZA','key_points'=>'IBY’INGENZI','published'=>'Yatangajwe','updated'=>'Yavuguruwe','copy'=>'KOPIYA LINK ↗','demo_title'=>'URUGERO RWO KUGERAGEZA:','demo_body'=>"Iyi nyandiko ni demo. Ntabwo ari amakuru yemejwe, kandi ntigomba gutangazwa nk'inkuru nyayo.",'photo'=>'Ifoto y’icyitegererezo','story'=>'INKURU','reporting'=>'UKO DUKORA INKURU ↗','video'=>"Video y'inkuru",'sources'=>'Inkomoko zisangirwa n’abasomyi','correction'=>'ICYAKOSOWE','contact'=>'Ubonye ikosa muri iyi nkuru?','contact_link'=>'Menyesha ubwanditsi.','facts'=>'Inkuru yizewe igomba kugira amakuru ashobora kugenzurwa.','related'=>'Izindi nkuru','related_i'=>'wasoma.'];
