<div class="container av-article-page-layout"><main id="main-content" class="article-shell"><div class="breadcrumb"><a href="<?=e(localized_path('',$requestedLanguage))?>"><?=e($ui['home'])?></a> <span>/</span> <a href="<?=e(localized_path('category.php?slug='.$a['category_slug'],$requestedLanguage))?>"><?=e(strtoupper($a['category_name']))?></a></div><header class="article-header"><span class="overline"><?=e(strtoupper(str_replace('_',' ',$a['type'])))?> / <?=e($a['category_name'])?></span><h1><?=e($a['title'])?></h1><?php if(!empty($a['subheadline'])):?><p class="article-subheadline"><?=e($a['subheadline'])?></p><?php endif;?><p class="article-deck"><?=e($a['summary'])?></p><?php if(!empty($a['key_points'])):?><div class="key-points"><b><?=e($ui['key_points'])?></b><ul><?php foreach(array_filter(preg_split('/\R/u',$a['key_points'])) as $point):?><li><?=e(trim($point))?></li><?php endforeach;?></ul></div><?php endif;?><div class="article-byline"><div class="author-icon"><?=e(mb_substr($a['author_name'],0,1))?></div><div><strong><a href="<?=e(localized_path('author.php?id='.$a['author_id'],$requestedLanguage))?>"><?=e($a['author_name'])?></a></strong><span><?=e($ui['published'])?>: <?=e(display_date($a['published_at']))?> · <?=e($ui['updated'])?>: <?=e(display_date($a['updated_at']))?> · <?=estimate_readtime($a['body'])?> min read</span></div><div class="byline-share"><button type="button" data-copy-url><?=e($ui['copy'])?></button></div></div><?php if($a['is_demo']):?><p class="demo-warning"><b><?=e($ui['demo_title'])?></b> <?=e($ui['demo_body'])?></p><?php endif;?></header>
