<div class="article-content-grid"><aside class="article-rail"><span><?=e($ui['story'])?> / <?=e(str_pad((string)$a['id'],3,'0',STR_PAD_LEFT))?></span><div class="rail-line"></div><a href="<?=e(localized_path('about.php',$requestedLanguage))?>#ethics"><?=e($ui['reporting'])?></a></aside><article class="article-prose"><?=implode('',array_map(fn($p)=>'<p>'.nl2br(e(trim($p))).'</p>',array_filter(preg_split('/\R\s*\R/u',trim($a['body'])))))?><?php if($a['video_url'] && preg_match('~^(https://www\.youtube\.com/watch\?v=|https://youtu\.be/)([A-Za-z0-9_-]{11})~',$a['video_url'],$m)):?><div class="video-frame"><iframe title="<?=e($ui['video'])?>" loading="lazy" allowfullscreen referrerpolicy="strict-origin-when-cross-origin" src="https://www.youtube-nocookie.com/embed/<?=e($m[2])?>"></iframe></div><?php endif;?>
<?php if($a['public_sources']):?><div class="article-sources"><strong><?=e($ui['sources'])?></strong><p><?=nl2br(e($a['public_sources']))?></p></div><?php endif;?>
