<div class="end-mark">✳</div><p class="editorial-contact"><?=e($ui['contact'])?> <a href="<?=e(localized_path('contact.php',$requestedLanguage))?>"><?=e($ui['contact_link'])?></a></p></article><aside class="article-aside"><span class="mini-label">AFRIVOX NEWS / EDITORIAL</span><b>FACTS FIRST.</b><p><?=e($ui['facts'])?></p></aside></div>
